<?php require_once __DIR__.'/includes/functions.php';$slug=trim($_GET['slug']??'');$s=$pdo->prepare('SELECT * FROM categories WHERE slug=?');$s->execute([$slug]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Category not found');}$page_title=$c['name'];$page_desc=$c['description'];require __DIR__.'/includes/header.php'; ?><section class="section-head"><div><span class="eyebrow">CATEGORY</span><h1><?=e($c['name'])?></h1><p><?=e($c['description'])?></p></div></section><div class="grid"><?php $s=$pdo->prepare("SELECT a.*,c.name category_name,c.slug category_slug FROM articles a JOIN categories c ON c.id=a.category_id WHERE c.id=? AND a.status='published' ORDER BY a.published_at DESC");$s->execute([$c['id']]);foreach($s as $a): ?><article class="card"><div class="thumb">INFOROVA</div><div class="card-body"><h3><a href="<?=article_url($a['slug'])?>"><?=e($a['title'])?></a></h3><p><?=e($a['excerpt'])?></p></div></article><?php endforeach; ?></div><?php require __DIR__.'/includes/footer.php'; ?>
